Signed-off-by: Ilpo Järvinen <ilpo.jarvinen@linux.intel.com>

Here is the root cause:
The bug is a systematic vulnerability in multiple `hp_populate_*_elements_from_package()` functions where the bounds check only validates the base index `elem` against the array count, but does not include the offset (`reqs` or `pos_values`) used to access consecutive elements in nested loops (e.g., `enum_obj[elem + reqs]`). This allows accessing array indices beyond the allocated size, leading to out-of-bounds memory reads.

Here is the patch:

 static int hp_populate_password_elements_from_package(union acpi_object *password_obj,
 						      int password_obj_count,
 						      int instance_id)
 {
 	char *str_value = NULL;
 	int value_len;
 	int ret;
 	u32 size;
 	u32 int_value = 0;
 	int elem;
 	int reqs;
 	int eloc;
 	int pos_values;
 	struct password_data *password_data = &bioscfg_drv.password_data[instance_id];

 	if (!password_obj)
 		return -EINVAL;

 	for (elem = 1, eloc = 1; elem < password_obj_count; elem++, eloc++) {
 		/* ONLY look at the first PASSWORD_ELEM_CNT elements */
 		if (eloc == PSWD_ELEM_CNT)
 			goto exit_package;

 		switch (password_obj[elem].type) {
 		case ACPI_TYPE_STRING:
 			if (PREREQUISITES != elem && PSWD_ENCODINGS != elem) {
 				ret = hp_convert_hexstr_to_str(password_obj[elem].string.pointer,
 							       password_obj[elem].string.length,
 							       &str_value, &value_len);
 				if (ret)
 					continue;
 			}
 			break;
 		case ACPI_TYPE_INTEGER:
 			int_value = (u32)password_obj[elem].integer.value;
 			break;
 		default:
 			pr_warn("Unsupported object type [%d]\n", password_obj[elem].type);
 			continue;
 		}

 		/* Check that both expected and read object type match */
 		if (expected_password_types[eloc] != password_obj[elem].type) {
 			pr_err("Error expected type %d for elem %d, but got type %d instead\n",
 			       expected_password_types[eloc], elem, password_obj[elem].type);
 			kfree(str_value);
 			return -EIO;
 		}

 		/* Assign appropriate element value to corresponding field*/
 		switch (eloc) {
 		case VALUE:
